def recorded(name,entry,operation):
    folder=OUT/'reproductions'/name; folder.mkdir(parents=True)
    row={'scenario':name,'candidate_sha':SHA,'entry':entry,'synthetic_inputs':True,
         'tracked_files_modified':False,'external_scientific_actions':0}
    try:
        row.update(operation(folder)); row['status']='PASS'
    except Exception as exc:
        row.update(status='FAIL',error_type=type(exc).__name__,error=str(exc))
    results.append(row)
    (OUT/'independent_results.json').write_text(json.dumps(results,indent=2),encoding='utf-8')
    print(name,row['status'],row.get('error',''),flush=True)

def refused(fn):
    try: fn()
    except (ValueError,PermissionError,RuntimeError,OSError,subprocess.TimeoutExpired) as exc:
        return {'error_type':type(exc).__name__,'error':str(exc)}
    raise AssertionError('operation unexpectedly accepted')

def make_campaign(folder,authorized=True):
    source=folder/'source'; source.mkdir()
    (source/'POSCAR').write_text(POSCAR,encoding='ascii')
    (source/'POTCAR').write_text('SYNTHETIC TEST ONLY, NO POTENTIAL DATA\n',encoding='ascii')
    lsf=folder/'source.lsf'; lsf.write_text('#!/bin/sh\n# inert synthetic job\nNP=2\n',encoding='ascii')
    alpha.WORKDIR=folder/'campaign'; alpha.SOURCE=source; alpha.LSF=lsf; alpha.CASES=[('case',1,.20)]
    alpha.setup(); alpha.check()
    job=alpha.WORKDIR/'case'
    assert (job/'script.lsf').read_bytes()==lsf.read_bytes()
    db=folder/'test.sqlite3'; migrate_registry(db)
    # Configure the existing real preflight's database default; do not replace it.
    submission.preflight.__kwdefaults__['learning_database']=db
    preflight=submission.preflight(job,'diagnostic_static')
    assert preflight['passed']
    thresholds=yaml.safe_load((ROOT/'configs/neb_agent/default_thresholds.yaml').read_text(encoding='utf-8'))
    # Explicit synthetic reviewed scientific-evidence fixtures, as in the B1 input
    # contract. alpha.check and canonical preflight actually validated the inputs.
    geometry={'status':'PASS','fixture_kind':'synthetic reviewed static bcc structure'}
    analysis={'status':'NO_OUTPUT','images':[],'fixture_kind':'synthetic unstarted static calculation'}
    for name,payload in [('geometry',geometry),('analysis',analysis)]:
        kind,producer=TRUSTED_ARTIFACTS[name]
        payload.update(document_kind=kind,producer=producer,source_files=[{'path':str(job/'INCAR'),'sha256':sha256_file(job/'INCAR')},{'path':str(job/'POSCAR'),'sha256':sha256_file(job/'POSCAR')}])
    evidence=decide_execution(geometry,analysis,thresholds,climb=False,path_reviewed=True,preflight=preflight)['EVIDENCE']
    for name in ('geometry','analysis','thresholds','preflight'):
        path=job/('submission_preflight.json' if name=='preflight' else name+'.json')
        write_json(path,evidence[name]); evidence['source_bindings'][name]={'path':str(path),'sha256':sha256_file(path)}
    digest=sha256_file(source/'POTCAR')
    if authorized:
        source_auth=job/'synthetic-authorization.txt'; source_auth.write_text('SYNTHETIC AUDIT AUTHORIZATION: simulate this one exact static submission only.\n',encoding='ascii')
        auth={'schema_version':1,'document_kind':'user_execution_authorization','action':ACTION,'calculation_kind':'diagnostic_static',
              'authorized_at':'2026-09-10T06:00:00Z','source':{'path':str(source_auth),'sha256':sha256_file(source_auth)},
              'target':{'server_alias':HOST,'remote_dir':'~/sbq/case'},'workdir_identity':workdir_identity(job),
              'bundle_sha256':preflight['bundle_sha256'],'evidence_sha256':execution_evidence_sha256(evidence),
              'potcar':{'source':'~/sbq/SYNTHETIC/POTCAR','sha256':digest,'spec_sha256':preflight['files']['POTCAR.spec']}}
        ap=job/'authorization.json'; write_json(ap,auth); evidence['authorization']=auth
        evidence['source_bindings']['authorization']={'path':str(ap),'sha256':sha256_file(ap)}
    decision=decide_execution(evidence['geometry'],evidence['analysis'],evidence['thresholds'],climb=False,path_reviewed=True,
                             preflight=preflight,authorization=evidence['authorization'],source_bindings=evidence['source_bindings'])
    assert decision['ALLOWED_ACTIONS']==([ACTION] if authorized else [])
    dp=folder/'gate.json'; write_json(dp,decision)
    manifest=folder/'routing.json'; write_json(manifest,{'case':{'workdir':str(job),'decision_path':str(dp),'host':HOST,
        'remote_dir':'~/sbq/case','potcar_source':'~/sbq/SYNTHETIC/POTCAR','potcar_sha256':digest,'action':ACTION}})
    return job,manifest

def execution_probe(folder,mode):
    job,manifest=make_campaign(folder,authorized=mode!='routing_without_authorization')
    transport=[]; dispatch=[]
    def fake_transport(argv):
        transport.append(argv)
        if 'bsub script.lsf' in argv[-1]:
            dispatch.append(argv)
            if mode=='timeout': raise subprocess.TimeoutExpired(argv,300)
            if mode=='uncertain_response': return subprocess.CompletedProcess(argv,0,'request accepted; job ID unavailable','')
        return subprocess.CompletedProcess(argv,0,'Job <54321> is submitted','')
    errors=[]
    with patch.object(submission,'_run',fake_transport):
        if mode=='no_manifest': errors.append(refused(lambda:alpha.submit()))
        elif mode=='routing_without_authorization': errors.append(refused(lambda:alpha.submit(manifest)))
        elif mode.startswith('stale:'):
            p=job/mode.split(':',1)[1]; p.write_bytes(p.read_bytes()+b'\nchanged after authorization\n')
            errors.append(refused(lambda:alpha.submit(manifest)))
        elif mode.startswith('legacy:'):
            p=job/mode.split(':',1)[1]; p.write_text('123\n' if p.suffix=='.jobid' else '{}',encoding='ascii'); before=p.read_bytes()
            errors.append(refused(lambda:alpha.submit(manifest))); assert p.read_bytes()==before
        elif mode=='run_lsf':
            old=job/'run.lsf'; old.write_text('legacy job bytes',encoding='ascii'); before=old.read_bytes()
            errors.append(refused(alpha.setup)); assert old.read_bytes()==before
        elif mode=='concurrent':
            barrier=threading.Barrier(2); real=submission.write_json_exclusive
            def at_reservation(path,payload):
                if path.name==submission.SUBMISSION_ATTEMPT_FILE: barrier.wait(timeout=15)
                return real(path,payload)
            with patch.object(submission,'write_json_exclusive',at_reservation):
                with ThreadPoolExecutor(max_workers=2) as pool: futures=[pool.submit(alpha.submit,manifest) for _ in range(2)]
            successes=sum(f.exception() is None for f in futures)
            errors=[{'error_type':type(f.exception()).__name__,'error':str(f.exception())} for f in futures if f.exception()]
            assert successes==1 and len(errors)==1 and len(dispatch)==1
        elif mode in {'receipt_loss','timeout','uncertain_response'}:
            real=submission.write_json_exclusive
            def write_receipt(path,payload):
                if mode=='receipt_loss' and path.name==submission.SUBMISSION_RECORD_FILE: raise OSError('simulated process loss after submit')
                return real(path,payload)
            with patch.object(submission,'write_json_exclusive',write_receipt): errors.append(refused(lambda:alpha.submit(manifest)))
            before=(job/submission.SUBMISSION_ATTEMPT_FILE).read_bytes()
            assert submission.submission_status(job)['status']==submission.UNKNOWN
            errors.append(refused(lambda:alpha.submit(manifest)))
            assert (job/submission.SUBMISSION_ATTEMPT_FILE).read_bytes()==before and len(dispatch)==1
        else:
            alpha.submit(manifest)
            saved=load_json_object(job/submission.SUBMISSION_ATTEMPT_FILE); receipt=submission.submission_status(job)
            assert receipt['status']=='SUBMITTED' and receipt['reservation_id']==saved['reservation_id'] and len(dispatch)==1
    expected=1 if mode in {'positive','concurrent','timeout','uncertain_response','receipt_loss'} else 0
    assert len(dispatch)==expected
    if expected==0: assert len(transport)==0
    return {'expected_dispatches':expected,'dispatches':len(dispatch),'transport_calls':len(transport),'errors':errors,
            'reservation_status':submission.submission_status(job)['status'],'valid_successes':1 if mode in {'positive','concurrent'} else 0}

for mode in ['no_manifest','routing_without_authorization','positive','concurrent',
