        return {'python_decision':direct['DECISION'],'file_decision':decision['DECISION'],'source_hash':sha256_file(folder/'summary.json'),'dispatches':0}
    case=bound_case(folder/'science'); summary=case['vfa']/'vfa_analysis.json'; gate,decision=claim_document(summary)
    assert decision['DECISION']=='VALIDATED_TS' and decision['ALLOWED_ACTIONS']==['APPROVE_TS_CANDIDATE']
    require_action(gate,'APPROVE_TS_CANDIDATE',decision['state_sha256'])
    for action in ['SUBMIT_VASP','START_DIMER','START_VFA','REPORT_FINAL_BARRIER']: refused(lambda:require_action(gate,action,decision['state_sha256']))
    before=summary.read_bytes()
    if mode.startswith('stale:'):
        owner,name=mode.split(':')[1:]; p=case[owner]/name; p.write_bytes(p.read_bytes()+b'\n')
        assert summary.read_bytes()==before
        error=refused(lambda:require_action(gate,'APPROVE_TS_CANDIDATE',decision['state_sha256']))
