        _,bad=claim_document(summary); assert not bad['TS_CLAIM_ALLOWED']
        return {'cross_object_decision':bad['DECISION'],'dispatches':0}
    return {'decision':decision['DECISION'],'actions':decision['ALLOWED_ACTIONS'],'execution_authorization':decision['execution_authorization'],'dispatches':0}
