 tree=ast.parse(text); aliases={}; parents={child:node for node in ast.walk(tree) for child in ast.iter_child_nodes(node)}
 module=relative.removesuffix('.py').replace('/','.'); package=module.split('.')[:-1]; deps=set()
 for n in ast.walk(tree):
