    parent=parents.get(n)
    while parent and not isinstance(parent,(ast.FunctionDef,ast.AsyncFunctionDef)): parent=parents.get(parent)
    sites.append({'file':relative,'function':parent.name if parent else '<module>','line':n.lineno,'api':resolved,'call':ast.unparse(n)})
  if isinstance(n,ast.Constant) and isinstance(n.value,str) and pattern.search(n.value):
